#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <limits.h>
#include <math.h>

/* ==========================================================================
 *  datacassettereader.c
 *
 *  Decodes a WAV file that was previously recorded from a cassette containing
 *  the data stream generated by datacassettewriter.c.
 *
 *  Detection method:
 *    - Looks for zero-crossings in the left audio channel
 *    - Measures the number of samples between consecutive zero-crossings
 *    - <= 7 samples  → treated as a '1'  (high frequency)
 *    - >= 8 samples  → treated as a '0'  (low frequency)
 *    - Sequences of identical bits are accumulated and only flushed when the
 *      bit value changes (or noise/silence is detected)
 *
 *  Frame format expected:
 *    Header 11010010 (decimal 210) + 1024 data bits + Trailer 00101101
 * ========================================================================= */

#define FRAMELENGTH   1024
#define FRAMES        (8*1024)
#define DATALENGTH    (FRAMELENGTH*FRAMES)
#define INTROLENGTH   8
#define OUTROLENGTH   8
#define BITLENGTH     (FRAMES*(INTROLENGTH+OUTROLENGTH+FRAMELENGTH))
#define SAMPLERATE    96000
#define ONEFREQ       9600
#define ZEROFREQ      4800
#define DATARATE      9600

/* Stereo 16-bit PCM sample */
typedef struct PCM16_stereo_s
{
    int16_t left;
    int16_t right;
} PCM16_stereo_t;


/*
 * Flush any pending sequence of ones or zeros that has been counted.
 * This is called when the bit value changes, when noise is detected,
 * or at the end of the file.
 */
void flush_last_sequence(FILE* outputdata_p,
                         int* onecount, int* zerocount,
                         int* databits, uint8_t* headerdetect,
                         int* frames, int* frameopen, int* payload,
                         int noise)
{
  int onesequence, zerosequence, i;

  /* ---- Flush a sequence of ones ---- */
  if ((*onecount >= 2 && *zerocount > 0) || (*onecount >= 1 && noise))
  {
    /* Convert raw half-period counts into actual bit counts
     * (a '1' consists of two half-periods) */
    onesequence = (int)((((double)*onecount) / 2.0) + 0.49);

    for (i = 0; i < onesequence; i++)
    {
      if (*frameopen == 1) *payload = *payload + 1;

      /* Only write the payload bits (not header/trailer) to the output */
      if (*frameopen == 1 && *payload <= 1024)
        fprintf(outputdata_p, "1");

      /* Shift the header detector and check for the known header pattern */
      *headerdetect = (*headerdetect << 1) + 1;
      if (*headerdetect == 210 && *frameopen == 0)   /* 210 == 0b11010010 */
      {
        printf("  --> Detected header at bit position %d, opening frame %d\n",
               *databits, *frames);
        fprintf(outputdata_p, "Frame %d\n", *frames);
        fprintf(outputdata_p, "Header: 11010010\n");
        *frames = *frames + 1;
        *frameopen = 1;
        *payload = 0;
      }

      /* After header + 1024 data bits we expect the trailer */
      if (*frameopen == 1 && *payload == 1032)
      {
        *frameopen = 0;
        fprintf(outputdata_p, "\nTrailer: 00101101\n");
        printf("  <-- Closed frame %d (payload complete)\n", *frames - 1);
      }
    }
    *databits = *databits + onesequence;
    *onecount = 0;
  }
  else
  /* ---- Flush a sequence of zeros ---- */
  if ((*zerocount >= 1 && *onecount > 0) || (*zerocount >= 1 && noise))
  {
    zerosequence = (int)((((double)*zerocount) / 1.0) + 0.49);

    for (i = 0; i < zerosequence; i++)
    {
      if (*frameopen == 1) *payload = *payload + 1;

      if (*frameopen == 1 && *payload <= 1024)
        fprintf(outputdata_p, "0");

      /* Shift header detector (add a zero bit) */
      *headerdetect = (*headerdetect << 1);
      if (*headerdetect == 210 && *frameopen == 0)
      {
        printf("  --> Detected header at bit position %d, opening frame %d\n",
               *databits, *frames);
        fprintf(outputdata_p, "Frame %d\n", *frames);
        fprintf(outputdata_p, "Header: 11010010\n");
        *frames = *frames + 1;
        *frameopen = 1;
        *payload = 0;
      }

      if (*frameopen == 1 && *payload == 1032)
      {
        *frameopen = 0;
        fprintf(outputdata_p, "\nTrailer: 00101101\n");
        printf("  <-- Closed frame %d (payload complete)\n", *frames - 1);
      }
    }
    *databits = *databits + zerosequence;
    *zerocount = 0;
  }
}


int main(void)
{
  FILE* file_p;
  FILE* outputdata_p;

  int i;
  int leftlast, leftnow;
  int leftcount = 0;
  int onecount = 0, zerocount = 0;
  int samplenumber = 0, databits = 0;
  uint8_t headerdetect = 0;
  int frames = 0;
  int frameopen = 0;
  int payload = 0;

  /* Statistics collected for diagnostics */
  int leftmax = 0, leftmin = 0;
  int leftmaxone = 0, leftminone = 100000000;
  int leftmaxzero = 0, leftminzero = 100000000;
  int betrag;
  int leftintegral = 0;
  int leftmaxonearea = 0, leftminonearea = 100000000;
  int leftmaxzeroarea = 0, leftminzeroarea = 100000000;

  PCM16_stereo_t *sample_p = NULL;
  sample_p = (PCM16_stereo_t *)malloc(sizeof(PCM16_stereo_t) * 1);
  if (sample_p == NULL) {
    fprintf(stderr, "ERROR: Failed to allocate sample buffer\n");
    return 1;
  }

  printf("=== datacassettereader starting ===\n");

  /* Open the recorded WAV file */
  file_p = fopen("output.wav", "r");
  if (file_p == NULL) {
    fprintf(stderr, "ERROR: Could not open output.wav for reading\n");
    free(sample_p);
    return 1;
  }
  printf("Opened output.wav\n");

  /* Open the text output file that will contain the recovered bits */
  outputdata_p = fopen("output.txt", "w");
  if (outputdata_p == NULL) {
    fprintf(stderr, "ERROR: Could not open output.txt for writing\n");
    fclose(file_p);
    free(sample_p);
    return 1;
  }
  printf("Opened output.txt for recovered data\n\n");

  /* Skip the WAV header (11 stereo samples is a rough approximation of the header size) */
  printf("Skipping WAV header...\n");
  for (i = 0; i < 11; i++) {
    fread(sample_p, sizeof(PCM16_stereo_t), 1, file_p);
  }

  /* Read the first real sample to initialise the edge detector */
  if (fread(sample_p, sizeof(PCM16_stereo_t), 1, file_p) != 1) {
    fprintf(stderr, "ERROR: WAV file appears to be empty or too short\n");
    fclose(file_p);
    fclose(outputdata_p);
    free(sample_p);
    return 1;
  }
  leftlast = sample_p[0].left;
  samplenumber++;

  printf("Starting sample-by-sample decoding...\n");

  /* Main decoding loop – process every sample looking for zero-crossings */
  while (fread(sample_p, sizeof(PCM16_stereo_t), 1, file_p))
  {
    samplenumber++;
    leftnow = sample_p[0].left;
    leftintegral += leftnow;
    leftcount++;

    /* Track overall amplitude extremes (for diagnostics) */
    if (leftnow > leftmax) leftmax = leftnow;
    if (leftnow < leftmin) leftmin = leftnow;

    /* Detect a zero-crossing (sign change) */
    if ((leftlast >= 0 && leftnow < 0) || (leftlast <= 0 && leftnow > 0))
    {
      /* We have a rising or falling edge */

      if (leftmax > 700 || leftmin < -700)   /* Signal is strong enough */
      {
        if (leftcount <= 7)
        {
          /* Short period → treat as a '1' */
          if (leftmax > 700)  betrag = leftmax;
          if (leftmin < -700) betrag = -leftmin;

          if (betrag > leftmaxone) leftmaxone = betrag;
          if (betrag < leftminone) leftminone = betrag;

          if (leftintegral < 0) leftintegral = -leftintegral;
          if (leftintegral > leftmaxonearea) leftmaxonearea = leftintegral;
          if (leftintegral < leftminonearea) leftminonearea = leftintegral;

          onecount++;
          leftintegral = 0;
        }
        else   /* leftcount >= 8 */
        {
          /* Longer period → treat as a '0'
           * Special case: the very first bit of the whole stream is forced to 1 */
          if (databits == 0 && onecount == 0)
          {
            onecount++;
          }
          else
          {
            if (leftmax > 700)  betrag = leftmax;
            if (leftmin < -700) betrag = -leftmin;

            if (betrag > leftmaxzero) leftmaxzero = betrag;
            if (betrag < leftminzero) leftminzero = betrag;

            if (leftintegral < 0) leftintegral = -leftintegral;
            if (leftintegral > leftmaxzeroarea) leftmaxzeroarea = leftintegral;
            if (leftintegral < leftminzeroarea) leftminzeroarea = leftintegral;

            zerocount++;
            leftintegral = 0;
          }
        }
      }
      else
      {
        /* Amplitude too low → treat as noise and flush any pending bits */
        flush_last_sequence(outputdata_p, &onecount, &zerocount,
                            &databits, &headerdetect,
                            &frames, &frameopen, &payload, 1);
        onecount = 0;
        zerocount = 0;
      }

      /* Reset counters for the next half-period */
      leftcount = 0;
      leftmax = 0;
      leftmin = 0;
    }
    else if (leftlast == 0 && leftnow == 0)
    {
      /* Complete silence detected */
      if (onecount != 0 || zerocount != 0)
      {
        /* A trailing half-one might have been lost */
        if (onecount == 1) onecount++;
        flush_last_sequence(outputdata_p, &onecount, &zerocount,
                            &databits, &headerdetect,
                            &frames, &frameopen, &payload, 1);
      }
      leftcount = 0;
      leftmax = 0;
      leftmin = 0;
    }

    /* Continuously try to flush completed sequences */
    flush_last_sequence(outputdata_p, &onecount, &zerocount,
                        &databits, &headerdetect,
                        &frames, &frameopen, &payload, 0);

    leftlast = sample_p[0].left;
  }

  /* Final flush at end of file */
  flush_last_sequence(outputdata_p, &onecount, &zerocount,
                      &databits, &headerdetect,
                      &frames, &frameopen, &payload, 1);

  /* Print summary statistics */
  printf("\n=== Decoding finished ===\n");
  printf("Samples processed          : %d\n", samplenumber);
  printf("Data bits recovered        : %d\n", databits);
  printf("Frames successfully opened : %d\n", frames);
  printf("\nAmplitude statistics (1s)  : max %d, min %d\n", leftmaxone, leftminone);
  printf("Amplitude statistics (0s)  : max %d, min %d\n", leftmaxzero, leftminzero);
  printf("Area statistics (1s)       : max %d, min %d\n", leftmaxonearea, leftminonearea);
  printf("Area statistics (0s)       : max %d, min %d\n", leftmaxzeroarea, leftminzeroarea);

  fclose(file_p);
  fclose(outputdata_p);
  free(sample_p);

  printf("\nRecovered data written to output.txt\n");
  return 0;
}
